  // ─────────────────────────────────────────────────────────────
  // 1. CONTEXTE (config, date, météo brute)
  // ─────────────────────────────────────────────────────────────
  const cfg    = $('Config').first().json || {};
  const now    = DateTime.now().setZone('Europe/Brussels').setLocale('fr');
  const daily  = $('Météo Hannut').first()?.json?.daily || {};

  // ─────────────────────────────────────────────────────────────
  // 2. LISTE DES VIDÉOS (Remplacez par vos URLs de vidéos MP4)
  // ─────────────────────────────────────────────────────────────
  const videos = [

    'https://i.imgur.com/ycnt1o4.mp4',

    'https://i.imgur.com/Ydq0Amg.mp4',

     'https://i.imgur.com/Sj6Jy5m.mp4'
  ];

  // ─────────────────────────────────────────────────────────────
  // 3. CHOIX DE LA VIDÉO (rotation cyclique)
  // ─────────────────────────────────────────────────────────────
  const lastVideo = String(
    $('Dernière vidéo utilisée1').first()?.json?.videoUrl || ''
  ).trim();

  const lastPos  = videos.indexOf(lastVideo);
  const idx      = lastPos === -1 ? 0 : (lastPos + 1) % videos.length;
  const videoUrl = videos[idx];

  // ─────────────────────────────────────────────────────────────
  // 4. MÉTÉO (mapping codes WMO → texte FR)
  // ─────────────────────────────────────────────────────────────
  const WEATHER_CODES = {
    0:  'ciel dégagé',       1:  'plutôt ensoleillé',
    2:  'partiellement nuageux', 3: 'couvert',
    45: 'brouillard',        48: 'brouillard givrant',
    51: 'bruine légère',     53: 'bruine',
    55: 'bruine dense',      56: 'bruine verglaçante',
    57: 'bruine verglaçante',61: 'pluie faible',
    63: 'pluie',             65: 'pluie soutenue',
    66: 'pluie verglaçante', 67: 'pluie verglaçante',
    71: 'neige faible',      73: 'neige',
    75: 'neige soutenue',    77: 'grains de neige',
    80: 'quelques averses',  81: 'averses',
    82: 'averses soutenues', 85: 'averses de neige',
    86: 'averses de neige',  95: 'orageux',
    96: 'orageux',           99: 'orageux'
  };

  let meteo = 'indisponible (ne mentionne pas la météo)';

  const hasWeather =
    Array.isArray(daily.weather_code) && daily.weather_code.length &&
    Array.isArray(daily.temperature_2m_max) && daily.temperature_2m_max.length;

  if (hasWeather) {
    const desc = WEATHER_CODES[daily.weather_code[0]] || 'temps variable';
    const tMin = Math.round(daily.temperature_2m_min[0]);
    const tMax = Math.round(daily.temperature_2m_max[0]);
    const rain = (daily.precipitation_sum && daily.precipitation_sum[0]) || 0;
    meteo = `${desc}, entre ${tMin}°C et ${tMax}°C, ${rain} mm de précipitations prévues`;
  }

  // ─────────────────────────────────────────────────────────────
  // 5. SAISON
  // ─────────────────────────────────────────────────────────────
  const month  = now.month;
  const saison =
    month >= 3 && month <= 5  ? 'printemps' :
    month >= 6 && month <= 8  ? 'été'       :
    month >= 9 && month <= 11 ? 'automne'   :
                                'hiver';

  // ─────────────────────────────────────────────────────────────
  // 6. ANGLE DU JOUR (rotation jour + vidéo)
  // ─────────────────────────────────────────────────────────────
  const ANGLES = [
    "Le confort d'un habitacle propre au quotidien",
    "La saleté ramenée de l'extérieur sur les tapis de sol",
    "Le bien-être des passagers sur des sièges propres",
    "Une voiture agréable pour les trajets en famille",
    "La sensation de fraîcheur en montant dans sa voiture",
    "Prendre soin de l'intérieur pour préserver sa voiture",
    "Les zones qu'on touche tous les jours : volant, poignées, tableau de bord",
    "Confier l'intérieur de sa voiture à un professionnel local de Hannut"
  ];
  const angle = ANGLES[(now.ordinal + idx) % ANGLES.length];

  // ─────────────────────────────────────────────────────────────
  // 7. PROMOTION
  // ─────────────────────────────────────────────────────────────
  const promoFin = String(cfg.promoFin || '').trim();

  const promoActive =
    (cfg.promoActive === true || cfg.promoActive === 'true') &&
    (!promoFin || now.toISODate() <= promoFin);

  const promo = promoActive ? String(cfg.promoTexte || '').trim() : '';

  let promoFinTexte = '';
  if (promo && promoFin) {
    const dt = DateTime.fromISO(promoFin);
    if (dt.isValid) promoFinTexte = dt.setLocale('fr').toFormat('d LLLL yyyy');
  }

  // ─────────────────────────────────────────────────────────────
  // 8. RÉSULTAT
  // ─────────────────────────────────────────────────────────────
  return {
    date:          now.toISODate(),
    dateFr:        now.toFormat('cccc d LLLL yyyy'),
    saison,
    meteo,
    angle,
    promo,
    promoFinTexte,
    videoIndex:    idx + 1,
    totalVideos:   videos.length,
    videoUrl
  };
})()) }}

={{ JSON.stringify((() => {
  // 1. Vérification de sécurité pour éviter le crash
  const textContent = $json.text;
  if (!textContent) {
    throw new Error("L'IA n'a pas renvoyé de texte. Vérifiez le nœud 'Rédaction IA' ou changez de modèle OpenRouter.");
  }

  const raw = String(textContent).replace(/\r/g, '').trim();

  // 2. Regex plus flexible (accepte le markdown comme **TITLE:**)
  const match = raw.match(/(?:\*\*)?TITLE(?:\*\*)?:\s*([\s\S]*?)\s*(?:\*\*)?BODY(?:\*\*)?:\s*([\s\S]*?)\s*(?:\*\*)?HASHTAGS(?:\*\*)?:\s*([\s\S]*)/i);

  if (!match) {
    throw new Error('Format IA invalide. Réponse brute : ' + raw.slice(0, 300));
  }

  const clean = s => s.replace(/\*\*/g, '').replace(/^\s*\[|\]\s*$/g, '').replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();

  let title = clean(match[1]).replace(/\s*([!?])$/, ' $1');
  const body = clean(match[2]);
  let tags = [...new Set(match[3].match(/#[\p{L}\p{N}_]+/gu) || [])];

  const words = title.split(/\s+/).filter(w => /[\p{L}\p{N}]/u.test(w));
  if (words.length > 6) title = title.split(/\s+/).slice(0, 6).join(' ');

  if (!title || !body) throw new Error('Titre ou texte vide');
  if (tags.length < 3) throw new Error('Moins de 3 hashtags');
  tags = tags.slice(0, 8);

  // 3. Récupération sécurisée du contexte
  const ctx = $('Préparer contexte')?.first()?.json || { promo: '', promoFinTexte: '' };

  const lignePromo = ctx.promo ? '🎁 Offre spéciale : ' + ctx.promo + (ctx.promoFinTexte ? ' jusqu\'au ' + ctx.promoFinTexte : '') : '';
  const liens = 'Visitez notre site : https://shorturl.at/FnGfv\nPour réserver votre place : https://shorturl.at/uQl9K';

  const message = [title, body, lignePromo, liens, tags.join(' ')].filter(Boolean).join('\n\n');

  return { 
    title: title, 
    body: body, 
    promo: ctx.promo || '', 
    hashtags: tags.join(' '), 
    message: message 
  };
})()) }}

