={{ JSON.stringify((() => {
  const cfg = $('Config2').first().json || {};
  const raw = String($json.text || '').replace(/\r/g, '').replace(/\*\*/g, '').trim();
  if (!raw) throw new Error("Réponse IA vide (le modèle n'a rien renvoyé)");

  const enleverEtiquettes = (s) => String(s || '')
    .replace(/^\s*(TITLE|TITRE|BODY|TEXTE|HASHTAGS?)\s*[:\-]\s*/gim, '')
    .replace(/^\s*\[|\]\s*$/g, '')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  let title = '', body = '', tagsRaw = '';
  const m = raw.match(/TITLE\s*:\s*([\s\S]*?)\s*BODY\s*:\s*([\s\S]*?)\s*HASHTAGS\s*:\s*([\s\S]*)$/i);

  if (m) {
    title = m[1];
    body = m[2];
    tagsRaw = m[3];
  } else {
    tagsRaw = (raw.match(/#[\p{L}\p{N}_]+/gu) || []).join(' ');
    const sansTags = raw.replace(/#[\p{L}\p{N}_]+/gu, '').replace(/\n{3,}/g, '\n\n').trim();
    const lignes = sansTags.split('\n').map(l => enleverEtiquettes(l)).filter(Boolean);
    if (!lignes.length) throw new Error('Contenu IA vide');
    if (lignes.length === 1) {
      title = lignes[0];
      body = lignes[0];
    } else {
      title = lignes[0];
      body = lignes.slice(1).join('\n');
    }
  }

  title = enleverEtiquettes(title).split('\n')[0];
  body = enleverEtiquettes(body);
  if (!title || !body) throw new Error('Titre ou texte vide');

  const mots = title.split(/\s+/).filter(Boolean);
  if (mots.length > 6) {
    title = mots.slice(0, 6).join(' ');
    while (title && /[\-–—:,;%€\/«»"']$/.test(title.trim())) {
      title = title.trim().replace(/[\-–—:,;%€\/«»"']$/, '').trim();
      const reste = title.split(/\s+/);
      if (/^[\d.,]+$/.test(reste[reste.length - 1] || '')) { reste.pop(); title = reste.join(' '); }
    }
  }
  title = title.replace(/\s*([!?])$/, ' $1').trim();
  if (!title) throw new Error('Titre vide après nettoyage');

  let tags = [...new Set(String(tagsRaw).match(/#[\p{L}\p{N}_]+/gu) || [])];
  const secours = ['#HakimAutoPropre', '#Hannut', '#NettoyageAuto', '#NettoyageInterieur', '#VoiturePropre'];
  for (const f of secours) {
    if (tags.length >= 3) break;
    if (!tags.includes(f)) tags.push(f);
  }
  tags = tags.slice(0, 8);

  const promoFin = String(cfg.promoFin || '').trim();
  const now = DateTime.now().setZone('Europe/Brussels').setLocale('fr');
  const promoActive = (cfg.promoActive === true || cfg.promoActive === 'true') && (!promoFin || now.toISODate() <= promoFin);
  const promo = promoActive ? String(cfg.promoTexte || '').trim() : '';
  let promoFinTexte = '';
  if (promo && promoFin) {
    const dt = DateTime.fromISO(promoFin);
    if (dt.isValid) promoFinTexte = dt.setLocale('fr').toFormat('d LLLL yyyy');
  }

  const lignePromo = promo ? '🎁 Offre spéciale : ' + promo + (promoFinTexte ? " jusqu'au " + promoFinTexte : '') : '';
  const liens = 'Visitez notre site : https://shorturl.at/FnGfv\nPour réserver votre place : https://shorturl.at/uQl9K';
  const message = [title, body, lignePromo, liens, tags.join(' ')].filter(Boolean).join('\n\n');

  return { title, body, promo, hashtags: tags.join(' '), message };
})()) }}
